import { ApiProperty } from '@nestjs/swagger';
import { IsUUID } from 'class-validator';

// Comes from a multipart/form-data body, next to the `file` part.
export class UploadCotejoPhotoDto {
  @ApiProperty({
    format: 'uuid',
    example: '01933b6e-7f2a-7c3d-9a1b-2f8e6c4d5a10',
    description:
      'UUID v7 generated by the driver app. It identifies the photo in the later accept call, and sending the same one again never uploads the photo twice.',
  })
  @IsUUID('7')
  photoId!: string;
}
